import phase2_feature as p2
core=pkg.core;db=pkg.db;app=pkg.app;REGISTERED=False

def tx_filter(q):
    a=request.args;start=p2._d(a.get('start'));end=p2._d(a.get('end'));bank=(a.get('bank') or '').strip();acct=(a.get('account') or '').strip();curr=(a.get('currency') or '').strip().upper();direction=a.get('direction') or '';dtype=a.get('data_type') or '';kw=(a.get('q') or '').strip()
    if start:q=q.filter(core.BankTransaction.transaction_date>=start)
    if end:q=q.filter(core.BankTransaction.transaction_date<=end)
    if bank:q=q.filter(core.BankAccount.financial_institution==bank)
    if acct:q=q.filter(core.BankAccount.account_number==acct)
    if curr:q=q.filter(core.BankAccount.currency==curr)
    if dtype=='krw':q=q.filter(core.BankAccount.currency=='KRW')
    elif dtype=='fx':q=q.filter(core.BankAccount.currency!='KRW')
    if direction=='deposit':q=q.filter(core.BankTransaction.deposit_amount>0)
    elif direction=='withdrawal':q=q.filter(core.BankTransaction.withdrawal_amount>0)
    if kw:
        like=f'%{kw}%';q=q.filter(or_(core.BankTransaction.description.ilike(like),core.BankTransaction.counterparty.ilike(like)))
    return q

def opts():
    banks=[x[0] for x in db.session.query(core.BankAccount.financial_institution).distinct().order_by(core.BankAccount.financial_institution)];accounts=core.BankAccount.query.order_by(core.BankAccount.financial_institution,core.BankAccount.account_number).all();curr=[x[0] for x in db.session.query(core.BankAccount.currency).distinct().order_by(core.BankAccount.currency)];return banks,accounts,curr

def register():
    global REGISTERED
    if REGISTERED:return
    @login_required
    def transactions():
        q=tx_filter(core.BankTransaction.query.join(core.BankAccount));total=q.count();per=int(request.args.get('per') or 100);per=per if per in (50,100,200) else 100;page=max(1,int(request.args.get('page') or 1));rows=q.order_by(core.BankTransaction.transaction_date.desc(),core.BankTransaction.transaction_time.desc().nullslast(),core.BankTransaction.source_row_number.asc(),core.BankTransaction.id.asc()).offset((page-1)*per).limit(per).all();mn,mx=db.session.query(func.min(core.BankTransaction.transaction_date),func.max(core.BankTransaction.transaction_date)).one();banks,accounts,curr=opts();dl=urlencode({k:v for k,v in request.args.items() if k not in ('page','per')});prev=urlencode({**request.args.to_dict(),'page':page-1,'per':per});nxt=urlencode({**request.args.to_dict(),'page':page+1,'per':per})
        body="""<div class='p2head'><div><h2>금융거래내역</h2><p class='muted'>거래자료 {{ mn or '-' }} ~ {{ mx or '-' }} · 조회 {{ total }}건</p></div><a class='btnlink' href='{{ url_for("financial_transactions_csv") }}?{{ dl }}'>현재 필터 CSV</a></div><form class='panel filters' method='get'><label>시작<input type='date' name='start' value='{{ request.args.get("start","") }}'></label><label>종료<input type='date' name='end' value='{{ request.args.get("end","") }}'></label><label>은행<select name='bank'><option value=''>전체</option>{% for x in banks %}<option {% if request.args.get('bank')==x %}selected{% endif %}>{{ x }}</option>{% endfor %}</select></label><label>계좌<select name='account'><option value=''>전체</option>{% for x in accounts %}<option value='{{ x.account_number }}' {% if request.args.get('account')==x.account_number %}selected{% endif %}>{{ x.account_number }} {{ x.currency }}</option>{% endfor %}</select></label><label>구분<select name='data_type'><option value=''>전체</option><option value='krw'>원화</option><option value='fx'>외화</option></select></label><label>통화<select name='currency'><option value=''>전체</option>{% for x in curr %}<option>{{ x }}</option>{% endfor %}</select></label><label>입출금<select name='direction'><option value=''>전체</option><option value='deposit'>입금</option><option value='withdrawal'>출금</option></select></label><label>검색<input name='q' value='{{ request.args.get("q","") }}'></label><label>건수<select name='per'>{% for n in [50,100,200] %}<option value='{{ n }}' {% if per==n %}selected{% endif %}>{{ n }}</option>{% endfor %}</select></label><button>조회</button></form><section class='panel scroll'><table><thead><tr><th>일자</th><th>시간</th><th>은행</th><th>계좌</th><th>통화</th><th>적요</th><th>상대방</th><th>입금</th><th>출금</th><th>잔액</th></tr></thead><tbody>{% for r in rows %}<tr><td>{{ r.transaction_date }}</td><td>{{ r.transaction_time or '-' }}</td><td>{{ r.account.financial_institution }}</td><td>{{ r.account.account_number }}</td><td>{{ r.account.currency }}</td><td>{{ r.description or '-' }}</td><td>{{ r.counterparty or '-' }}</td><td>{{ fmt(r.deposit_amount,r.account.currency) }}</td><td>{{ fmt(r.withdrawal_amount,r.account.currency) }}</td><td>{{ fmt(r.balance,r.account.currency) }}</td></tr>{% else %}<tr><td colspan='10'>조회결과 없음</td></tr>{% endfor %}</tbody></table></section><div class='actions'>{% if page>1 %}<a href='?{{ prev }}'>이전</a>{% endif %}{% if page*per<total %}<a href='?{{ nxt }}'>다음</a>{% endif %}</div>""";return p2._render('금융거래내역',body,rows=rows,total=total,per=per,page=page,mn=mn,mx=mx,banks=banks,accounts=accounts,curr=curr,dl=dl,prev=prev,nxt=nxt,request=request)
    @login_required
    def transactions_csv():
        rows=tx_filter(core.BankTransaction.query.join(core.BankAccount)).order_by(core.BankTransaction.transaction_date,core.BankTransaction.transaction_time.asc().nullsfirst(),core.BankTransaction.source_row_number,core.BankTransaction.id).all();o=io.StringIO();w=csv.writer(o);w.writerow(['일자','시간','은행','계좌','통화','적요','상대방','입금','출금','잔액','Batch']);[w.writerow([r.transaction_date,r.transaction_time or '',r.account.financial_institution,r.account.account_number,r.account.currency,r.description or '',r.counterparty or '',r.deposit_amount,r.withdrawal_amount,r.balance,r.batch.batch_code]) for r in rows];return Response('\ufeff'+o.getvalue(),mimetype='text/csv; charset=utf-8',headers={'Content-Disposition':'attachment; filename=bank_transactions_filtered.csv'})
    def class_query():
        q=db.session.query(core.BankTransaction,p2.TransactionAnnotation).join(core.BankAccount).outerjoin(p2.TransactionAnnotation,p2.TransactionAnnotation.transaction_id==core.BankTransaction.id);a=request.args;start=p2._d(a.get('start'));end=p2._d(a.get('end'));bank=(a.get('bank') or '').strip();acct=(a.get('account') or '').strip();curr=(a.get('currency') or '').strip();direction=a.get('direction') or '';flow=a.get('flow_type') or '';cat=a.get('category_id') or '';cp=(a.get('counterparty') or '').strip();kw=(a.get('q') or '').strip()
        if start:q=q.filter(core.BankTransaction.transaction_date>=start)
        if end:q=q.filter(core.BankTransaction.transaction_date<=end)
        if bank:q=q.filter(core.BankAccount.financial_institution==bank)
        if acct:q=q.filter(core.BankAccount.account_number==acct)
        if curr:q=q.filter(core.BankAccount.currency==curr)
        if direction=='deposit':q=q.filter(core.BankTransaction.deposit_amount>0)
        elif direction=='withdrawal':q=q.filter(core.BankTransaction.withdrawal_amount>0)
        if flow:q=q.filter(p2.TransactionAnnotation.flow_type==flow)
        if cat=='unclassified':q=q.filter(p2.TransactionAnnotation.category_id.is_(None))
        elif cat:q=q.filter(p2.TransactionAnnotation.category_id==cat)
