    @login_required
    def core_view():
        latest=db.session.query(func.max(core.BankTransaction.transaction_date)).scalar();day=p2._d(request.args.get('date'),latest or date.today());rows=db.session.execute(text('SELECT a.financial_institution,a.account_number,a.currency,d.previous_balance,d.deposit_total,d.withdrawal_total,d.calculated_balance,d.bank_reported_balance,d.difference,d.status,d.is_carry_forward FROM bank_accounts a LEFT JOIN daily_balance_checks d ON d.bank_account_id=a.id AND d.check_date=:d WHERE a.is_active=TRUE ORDER BY a.financial_institution,a.account_number,a.currency'),{'d':day}).all();body="""<div class='p2head'><div><h2>{{ day }} 자금일보 Core</h2><p class='muted'>전일잔액 + 당일입금 - 당일출금 = 당일잔액</p></div></div><form class='panel filters'><label>기준일<input type='date' name='date' value='{{ day }}'></label><button>조회</button></form><section class='panel scroll'><table><tr><th>은행</th><th>계좌</th><th>통화</th><th>전일잔액</th><th>입금</th><th>출금</th><th>당일잔액</th><th>은행잔액</th><th>차이</th><th>상태</th></tr>{% for r in rows %}<tr><td>{{ r[0] }}</td><td>{{ r[1] }}</td><td>{{ r[2] }}</td><td>{{ fmt(r[3],r[2]) }}</td><td>{{ fmt(r[4],r[2]) }}</td><td>{{ fmt(r[5],r[2]) }}</td><td>{{ fmt(r[6],r[2]) }}</td><td>{{ fmt(r[7],r[2]) }}</td><td>{{ fmt(r[8],r[2]) }}</td><td>{{ '정상(이월)' if r[10] else ('정상' if r[9]=='ok' else '확인필요') }}</td></tr>{% endfor %}</table></section>""";return p2._render('자금일보 Core',body,day=day,rows=rows)
    app.view_functions['financial_transactions']=transactions;app.view_functions['financial_transactions_csv']=transactions_csv;app.view_functions['phase2_classifications']=classifications;app.add_url_rule('/reference/classifications.csv','phase25_classification_csv',class_csv,methods=['GET']);app.add_url_rule('/cash-journal/core','phase25_cash_core',core_view,methods=['GET']);REGISTERED=True
